def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()
    objs = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            mask = [[grid[y][x] == color for x in range(c0, c1 + 1)]
                    for y in range(r0, r1 + 1)]
            objs.append((r0, c0, color, mask, r1-r0+1, c1-c0+1))

    square_sizes = sorted({
        o[4] for o in objs
        if o[4] == o[5] and o[4] >= 3
    }, reverse=True)

    for big in square_sizes:
        frames = [o for o in objs if o[4] == big and o[5] == big]
        smaller_sizes = [s for s in square_sizes if s < big]
        for small in smaller_sizes:
            patterns = [o for o in objs if o[4] == small and o[5] == small]
            if len(frames) >= 2 and len(patterns) >= len(frames):
                frames.sort(key=lambda o: (o[0], o[1]))
                patterns.sort(key=lambda o: (o[0], o[1]))
                tiles = []
                for frame, pat in zip(frames, patterns):
                    n, m = frame[4], pat[4]
                    tile = [[frame[2]] * n for _ in range(n)]
                    top, left = (n - m) // 2, (n - m) // 2
                    for y in range(m):
                        for x in range(m):
                            if pat[3][y][x]:
                                tile[top+y][left+x] = pat[2]
                    tiles.append(tile)

                cols = 2
                out = []
                for tr in range((len(tiles) + cols - 1) // cols):
                    for y in range(big):
                        row = []
                        for tc in range(cols):
                            i = tr * cols + tc
                            if i < len(tiles):
                                row.extend(tiles[i][y])
                        if row:
                            out.append(row)
                return out
    return grid
